#define TBOX_STYLE_GRID_PLACEMENT_FIELD(member) TBOX_STYLE_GROUP_FIELD(TBOX_STYLE_GROUP_GRID_PLACEMENT, tbox_style_grid_placement, member)
#define TBOX_STYLE_ANIMATION_FIELD(member) TBOX_STYLE_GROUP_FIELD(TBOX_STYLE_GROUP_ANIMATION, tbox_style_animation_lists, member)
/* A whole out-of-line group: overlaps every field of it. */
#define TBOX_STYLE_WHOLE_GROUP(group, type) { 0, sizeof(type), group }
#define TBOX_STYLE_MAX_FIELDS 24

typedef struct tbox_style_property_fields {
    const char *name;
    bool inherited;
    tbox_style_field fields[TBOX_STYLE_MAX_FIELDS]; /* ends at the first zero size */
} tbox_style_property_fields;

